package in.aicon.pocket;
import android.content.Context;import android.graphics.*;import android.view.*;import java.time.LocalDate;
/** Seven daily expense bars. Values are integer minor units from the selected ledger. */
final class WeekChart extends View {
 final long[] values;final LocalDate start;final int fg,muted,accent,soft;final Paint p=new Paint(3);java.util.function.IntConsumer onDay=i->{};
 WeekChart(Context c,long[] values,LocalDate start,int fg,int muted,int accent,int soft){super(c);this.values=values.clone();this.start=start;this.fg=fg;this.muted=muted;this.accent=accent;this.soft=soft;setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);}
 @Override protected void onDraw(Canvas c){float d=getResources().getDisplayMetrics().density,w=getWidth(),h=getHeight(),left=7*d,right=w-7*d,bottom=h-27*d,top=30*d;long max=1;for(long v:values)max=Math.max(max,v);float slot=(right-left)/7;p.setTypeface(AppFonts.face(getContext(),false));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(10*d);for(int i=0;i<7;i++){float x=left+slot*(i+.5f);p.setColor(muted);String label=String.valueOf(start.plusDays(i).getDayOfMonth());c.drawText(label,x,h-7*d,p);float height=(float)((double)values[i]/max)*(bottom-top);p.setColor(i==6?accent:QuickActivity.mix(soft,accent,.35f));c.drawRoundRect(new RectF(x-slot*.23f,bottom-Math.max(2*d,height),x+slot*.23f,bottom),5*d,5*d,p);if(values[i]>0){p.setColor(muted);p.setTextSize(9*d);String value=java.math.BigDecimal.valueOf(values[i],2).stripTrailingZeros().toPlainString();if(value.length()>6)value=java.math.BigDecimal.valueOf(values[i],5).setScale(1,java.math.RoundingMode.HALF_UP).toPlainString()+"k";c.drawText(value,x,bottom-height-7*d,p);p.setTextSize(10*d);}}p.setTextAlign(Paint.Align.LEFT);}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==android.view.MotionEvent.ACTION_DOWN)return true;if(e.getActionMasked()==android.view.MotionEvent.ACTION_UP){performClick();int index=Math.max(0,Math.min(6,(int)(e.getX()/Math.max(1,getWidth())*7)));onDay.accept(index);return true;}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
